import{_ as d,o as e,c as a,ag as o}from"./chunks/framework.CrXGS008.js";const u=JSON.parse('{"title":"Ajustes","description":"","frontmatter":{},"headers":[],"relativePath":"es/car-wash/settings.md","filePath":"es/car-wash/settings.md"}'),r={name:"es/car-wash/settings.md"};function s(n,t,c,l,i,h){return e(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="ajustes" tabindex="-1">Ajustes <a class="header-anchor" href="#ajustes" aria-label="Permalink to &quot;Ajustes&quot;">​</a></h1><p>Todos los ajustes de Car Wash se editan en <code>/nay</code>, en la página <strong>Car Wash</strong> (scope <code>nay_car_wash.config</code>). Los cambios se guardan en la base de datos y se aplican al instante a todos los jugadores. <code>config.lua</code> contiene valores iniciales opcionales: se aplican hasta que se cambia un ajuste en <code>/nay</code>, y <strong>Restablecer</strong> vuelve a ellos.</p><p>La columna <strong>En /nay</strong> es el nombre que muestra el panel. La clave es el nombre que usan <code>config.lua</code> y la <a href="/es/nay-lib/api">API HTTP</a>.</p><h2 id="general" tabindex="-1">General <a class="header-anchor" href="#general" aria-label="Permalink to &quot;General&quot;">​</a></h2><table tabindex="0"><thead><tr><th>En /nay</th><th>Clave</th><th>Tipo</th><th>Por defecto</th><th>Descripción</th></tr></thead><tbody><tr><td>Activado</td><td><code>Enabled</code></td><td>sí / no</td><td>sí</td><td>Activa o desactiva todos los túneles e hidrolimpiadoras.</td></tr><tr><td>Interacción a pie</td><td><code>InteractionMode</code></td><td><code>key</code> o <code>target</code></td><td><code>key</code></td><td>Cómo inician los jugadores una hidrolimpiadora: aviso de tecla (E) u ojo del target. Los túneles siempre usan E desde el vehículo.</td></tr><tr><td>Cuenta de pago</td><td><code>Account</code></td><td><code>cash</code>, <code>bank</code> o <code>cash_then_bank</code></td><td><code>cash_then_bank</code></td><td>De dónde se cobra el precio. <code>cash_then_bank</code> usa el banco cuando no hay suficiente efectivo.</td></tr><tr><td>Descuentos por trabajo</td><td><code>JobDiscounts</code></td><td>lista, hasta 32</td><td>ninguno</td><td>Descuentos para un trabajo a partir de un rango, en túneles e hidrolimpiadoras.</td></tr></tbody></table><p>Entradas de <strong>Descuentos por trabajo</strong>:</p><table tabindex="0"><thead><tr><th>En /nay</th><th>Clave</th><th>Tipo</th><th>Descripción</th></tr></thead><tbody><tr><td>Trabajo</td><td><code>Job</code></td><td>texto, de 1 a 32 caracteres</td><td>Nombre del trabajo, como en tu framework.</td></tr><tr><td>Rango mínimo</td><td><code>MinGrade</code></td><td>número, de 0 a 100</td><td>Rango más bajo que obtiene el descuento.</td></tr><tr><td>Descuento (%)</td><td><code>Percent</code></td><td>número, de 1 a 100</td><td>Descuento en porcentaje. 100 lo hace gratis.</td></tr></tbody></table><h2 id="tuneles" tabindex="-1">Túneles <a class="header-anchor" href="#tuneles" aria-label="Permalink to &quot;Túneles&quot;">​</a></h2><table tabindex="0"><thead><tr><th>En /nay</th><th>Clave</th><th>Tipo</th><th>Por defecto</th><th>Descripción</th></tr></thead><tbody><tr><td>Programas de lavado</td><td><code>Programs</code></td><td>lista, de 1 a 8</td><td>Express $150, Standard $250, Premium $400</td><td>Programas de lavado ofrecidos en todos los túneles.</td></tr><tr><td>Túneles</td><td><code>Tunnels</code></td><td>lista, hasta 32</td><td>Strawberry, Little Seoul</td><td>Los túneles. Se colocan con el <a href="/es/car-wash/tunnels">editor de túneles</a>.</td></tr><tr><td>Ancho máximo del vehículo (m)</td><td><code>MaxVehicleWidth</code></td><td>metros, de 1 a 6</td><td>2,25</td><td>Los vehículos más anchos se rechazan.</td></tr><tr><td>Clases de vehículo bloqueadas</td><td><code>BlockedClasses</code></td><td>lista de clases de vehículo</td><td>motos, bicicletas, barcos, helicópteros, aviones, trenes</td><td>Clases de vehículo rechazadas en la entrada.</td></tr><tr><td>Rechazar vehículos limpios</td><td><code>RequireDirt</code></td><td>sí / no</td><td>no</td><td>Rechaza los vehículos que ya están limpios.</td></tr><tr><td>Sustituir los IPL de los lavaderos del mapa</td><td><code>ReplaceMapIpls</code></td><td>sí / no</td><td>sí</td><td>En Strawberry, sustituye el lavadero original por su versión sin cepillos. Desactívalo si un mapa personalizado o un gestor de mapping se encarga de ese lavadero.</td></tr></tbody></table><p>Entradas de <strong>Programas de lavado</strong>:</p><table tabindex="0"><thead><tr><th>En /nay</th><th>Clave</th><th>Tipo</th><th>Descripción</th></tr></thead><tbody><tr><td>Nombre</td><td><code>Label</code></td><td>texto, de 1 a 32 caracteres</td><td>Nombre que se muestra en el menú de lavado.</td></tr><tr><td>Precio</td><td><code>Price</code></td><td>número, de 0 a 1000000</td><td>Precio antes de descuentos y del porcentaje del túnel.</td></tr><tr><td>Velocidad (%)</td><td><code>SpeedPercent</code></td><td>número, de 25 a 300</td><td>Velocidad relativa a la del túnel.</td></tr><tr><td>Jabón</td><td><code>Soap</code></td><td>sí / no</td><td>Activa el arco de jabón.</td></tr><tr><td>Aclarado</td><td><code>Rinse</code></td><td>sí / no</td><td>Activa el arco de aclarado.</td></tr><tr><td>Secado</td><td><code>Dry</code></td><td>sí / no</td><td>Activa el secador.</td></tr><tr><td>Cera (minutos)</td><td><code>WaxMinutes</code></td><td>número, de 0 a 1440</td><td>Minutos que el vehículo sigue limpio después del lavado. 0 significa sin cera.</td></tr></tbody></table><p>Las entradas de <strong>Túneles</strong> son más fáciles de editar con el <a href="/es/car-wash/tunnels">editor de túneles</a>, que rellena estos campos por ti:</p><table tabindex="0"><thead><tr><th>En /nay</th><th>Clave</th><th>Tipo</th><th>Descripción</th></tr></thead><tbody><tr><td>Nombre</td><td><code>Label</code></td><td>texto, hasta 48 caracteres</td><td>Título del menú de lavado, usado también en el historial y en los webhooks. Opcional.</td></tr><tr><td>Abierto</td><td><code>Enabled</code></td><td>sí / no</td><td>Cierra un túnel sin eliminarlo.</td></tr><tr><td>Entrada</td><td><code>Entry</code></td><td>posición y orientación</td><td>Donde el conductor se detiene y pulsa E.</td></tr><tr><td>Inicio de línea</td><td><code>Start</code></td><td>posición</td><td>Inicio de la línea que sigue el vehículo.</td></tr><tr><td>Fin de línea</td><td><code>Finish</code></td><td>posición</td><td>Fin de la línea.</td></tr><tr><td>Ancho (m)</td><td><code>Width</code></td><td>metros, de 2 a 10</td><td>Ancho del carril: dimensiona los arcos, limita el ancho del vehículo (margen de 0,5 m) y lo usa la comprobación de carril bloqueado.</td></tr><tr><td>Velocidad (m/s)</td><td><code>Speed</code></td><td>metros por segundo, de 0,5 a 8</td><td>Velocidad base en el túnel, multiplicada por la velocidad del programa.</td></tr><tr><td>Precio (%)</td><td><code>PricePercent</code></td><td>número, de 0 a 1000</td><td>Porcentaje aplicado a cada precio de programa en este túnel. 100 mantiene los precios.</td></tr><tr><td>Arco de jabón</td><td><code>SoapJet</code></td><td>posición</td><td>Arco de jabón.</td></tr><tr><td>Cepillo superior</td><td><code>HorizontalRoller</code></td><td>posición</td><td>Cepillo superior.</td></tr><tr><td>Cepillos laterales</td><td><code>VerticalRoller</code></td><td>posición</td><td>Cepillos laterales.</td></tr><tr><td>Arco de aclarado</td><td><code>RinseJet</code></td><td>posición</td><td>Arco de aclarado.</td></tr><tr><td>Secador</td><td><code>Dryer</code></td><td>posición</td><td>Secador de vapor. Opcional.</td></tr></tbody></table><p>Las entradas de <strong>Clases de vehículo bloqueadas</strong> tienen un solo campo, <strong>Clase</strong> (<code>Class</code>), que se elige por nombre entre las clases de vehículo de GTA.</p><h2 id="hidrolimpiadoras" tabindex="-1">Hidrolimpiadoras <a class="header-anchor" href="#hidrolimpiadoras" aria-label="Permalink to &quot;Hidrolimpiadoras&quot;">​</a></h2><table tabindex="0"><thead><tr><th>En /nay</th><th>Clave</th><th>Tipo</th><th>Por defecto</th><th>Descripción</th></tr></thead><tbody><tr><td>Hidrolimpiadoras</td><td><code>ManualEnabled</code></td><td>sí / no</td><td>sí</td><td>Activa o desactiva las hidrolimpiadoras.</td></tr><tr><td>Props de hidrolimpiadora</td><td><code>ManualModels</code></td><td>lista, hasta 16</td><td><code>prop_gas_airunit01</code></td><td>Props del mundo que se convierten en hidrolimpiadoras, allí donde el mapa los tenga.</td></tr><tr><td>Hidrolimpiadoras colocadas</td><td><code>ManualStations</code></td><td>lista, hasta 64</td><td>ninguna</td><td>Hidrolimpiadoras que colocas tú mismo.</td></tr><tr><td>Precio por nivel de suciedad</td><td><code>ManualPricePerLevel</code></td><td>número, de 0 a 100000</td><td>15</td><td>Precio de un nivel de suciedad, antes de los descuentos por trabajo.</td></tr><tr><td>Segundos por nivel de suciedad</td><td><code>ManualSecondsPerLevel</code></td><td>segundos, de 0,2 a 10</td><td>1</td><td>Tiempo para limpiar un nivel de suciedad.</td></tr></tbody></table><p>Las entradas de <strong>Props de hidrolimpiadora</strong> tienen un solo campo, <strong>Nombre del modelo</strong> (<code>Model</code>): el nombre del modelo del prop (letras, cifras y guiones bajos).</p><p>Entradas de <strong>Hidrolimpiadoras colocadas</strong>:</p><table tabindex="0"><thead><tr><th>En /nay</th><th>Clave</th><th>Tipo</th><th>Descripción</th></tr></thead><tbody><tr><td>Nombre</td><td><code>Label</code></td><td>texto, hasta 48 caracteres</td><td>Nombre de la estación, usado en el historial y en los webhooks. Opcional.</td></tr><tr><td>Posición</td><td><code>Coords</code></td><td>posición y orientación</td><td>Dónde está. <strong>Usar mi posición</strong> la rellena con el lugar donde estás.</td></tr></tbody></table><p>Más información en la página <a href="/es/car-wash/pressure-washers">Hidrolimpiadoras</a>.</p><h2 id="blips" tabindex="-1">Blips <a class="header-anchor" href="#blips" aria-label="Permalink to &quot;Blips&quot;">​</a></h2><table tabindex="0"><thead><tr><th>En /nay</th><th>Clave</th><th>Tipo</th><th>Por defecto</th><th>Descripción</th></tr></thead><tbody><tr><td>Mostrar blips</td><td><code>ShowBlips</code></td><td>sí / no</td><td>sí</td><td>Muestra en el mapa los túneles y, mientras las hidrolimpiadoras están activadas, las estaciones colocadas.</td></tr><tr><td>Icono del blip</td><td><code>BlipSprite</code></td><td>icono de blip</td><td>100</td><td>Se elige en una lista visual de iconos. Se puede seguir escribiendo cualquier número para un blip personalizado.</td></tr><tr><td>Color del blip</td><td><code>BlipColor</code></td><td>color de blip</td><td>63</td><td>Se elige en una lista visual de colores.</td></tr><tr><td>Tamaño del blip</td><td><code>BlipScale</code></td><td>de 0,2 a 2</td><td>0,8</td><td>Tamaño del blip.</td></tr></tbody></table>',22)])])}const b=d(r,[["render",s]]);export{u as __pageData,b as default};
